<?php
declare(strict_types=1);
require_once __DIR__ . '/store.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$query = db()->prepare('SELECT p.*, c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1'); $query->execute([$id]); $product=$query->fetch();
if (!$product) { http_response_code(404); exit('Product not found.'); }
$final=(float)$product['price']*(1-(float)$product['discount_percent']/100);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($product['name']) ?></title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><header class="site-header"><a class="brand" href="index.php">Sanderi <span>Stationary</span></a><nav class="nav"><a href="products.php">Shop</a><a href="cart.php">Cart</a></nav></header><main class="page-shell"><section class="detail-grid"><div class="detail-image" style="background-image:url('<?= htmlspecialchars($product['image_url'] ?: 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=900') ?>')"></div><div><div class="eyebrow"><?= htmlspecialchars($product['category_name'] ?? '') ?></div><h1><?= htmlspecialchars($product['name']) ?></h1><p><?= nl2br(htmlspecialchars($product['description'])) ?></p><p><strong>Standard:</strong> <?= htmlspecialchars($product['standard'] ?: 'All') ?> · <strong>Subject:</strong> <?= htmlspecialchars($product['subject'] ?: 'General') ?></p><p><strong>Publisher:</strong> <?= htmlspecialchars($product['publisher'] ?: 'Not specified') ?><?php if($product['isbn']): ?> · <strong>ISBN:</strong> <?= htmlspecialchars($product['isbn']) ?><?php endif; ?></p><h2>₹<?= number_format($final,2) ?> <?php if($product['discount_percent']>0): ?><del>₹<?= number_format((float)$product['price'],2) ?></del><?php endif; ?></h2><p class="stock"><?= $product['stock'] ? $product['stock'].' available' : 'Out of Stock' ?></p><form method="post" action="cart-add.php" class="buy-form"><input type="hidden" name="product_id" value="<?= $product['id'] ?>"><input type="number" name="quantity" min="1" max="<?= $product['stock'] ?>" value="1"><button <?= $product['stock'] ? '' : 'disabled' ?>>Add to cart</button></form></div></section></main></body></html>
